'use strict';
(()=>{const $=id=>document.getElementById(id);let running=false,timer=null;const cache=new Map();
function bytes(raw){const s=atob(raw),a=new Uint8Array(s.length);for(let i=0;i<s.length;i++)a[i]=s.charCodeAt(i);return a;}
function record(t,f){const key=t+':'+f;if(!cache.has(key)){const raw=B5.frames[t].fields[f];cache.set(key,{values:new Float32Array(bytes(raw.values).buffer),mask:bytes(raw.mask),metrics:raw.metrics});}return cache.get(key);}
function color(v,s){const q=Math.max(-1,Math.min(1,v/s)),a=Math.abs(q),c=q<0?[29,78,137]:[172,32,50];return c.map(x=>Math.round(243*(1-a)+x*a));}
function draw(id,v,mask,scale){const c=$(id),ctx=c.getContext('2d'),im=ctx.createImageData(72,35);for(let i=0;i<2520;i++){const rgb=color(v[i],scale);for(let j=0;j<3;j++)im.data[4*i+j]=rgb[j];im.data[4*i+3]=255;}const small=document.createElement('canvas');small.width=72;small.height=35;small.getContext('2d').putImageData(im,0,0);ctx.imageSmoothingEnabled=false;ctx.drawImage(small,0,0,720,350);if($('mask').checked){ctx.strokeStyle='#ffb128';ctx.lineWidth=1.4;ctx.beginPath();for(let i=0;i<2520;i++){if(!mask[i])continue;const row=Math.floor(i/72),col=i%72,x=col*10,y=row*10;if(row===0||!mask[i-72]){ctx.moveTo(x,y);ctx.lineTo(x+10,y);}if(row===34||!mask[i+72]){ctx.moveTo(x,y+10);ctx.lineTo(x+10,y+10);}if(!mask[row*72+(col+71)%72]){ctx.moveTo(x,y);ctx.lineTo(x,y+10);}if(!mask[row*72+(col+1)%72]){ctx.moveTo(x+10,y);ctx.lineTo(x+10,y+10);}}ctx.stroke();}}
function render(){try{const t=+$('time').value,f=+$('field').value,l=+$('degree').value,r=record(t,f),n=2520,metric=r.metrics[l],s=B5.scales[f];draw('original',r.values.subarray(0,n),r.mask,s);draw('fit',r.values.subarray((1+2*l)*n,(2+2*l)*n),r.mask,s);draw('residual',r.values.subarray((2+2*l)*n,(3+2*l)*n),r.mask,s);$('clock').textContent='t = '+B5.frames[t].t.toFixed(4)+' M';$('r2').textContent=(100*metric.R2).toFixed(4)+'%';$('rms').textContent=(100*metric.residual_RMS_over_original_SD).toFixed(3)+'%';$('dice').textContent=metric.dice.toFixed(4);$('inside').textContent=(100*metric.residual_squared_norm_fraction_in_original_mask).toFixed(3)+'%';$('limits').innerHTML='<span>−'+s.toPrecision(4)+'</span><span>0</span><span>+'+s.toPrecision(4)+'</span>';$('loading').hidden=true;}catch(e){stop();$('error').textContent='Не удалось прочитать массивы: '+e.message;}}
function stop(){running=false;clearInterval(timer);$('play').textContent='Пуск';$('play').setAttribute('aria-pressed','false');}
for(const id of ['field','degree','mask'])$(id).addEventListener('change',render);$('time').addEventListener('input',()=>{stop();render();});$('play').addEventListener('click',()=>{if(running){stop();return;}if(+$('time').value===54)$('time').value=0;running=true;$('play').textContent='Пауза';$('play').setAttribute('aria-pressed','true');render();timer=setInterval(()=>{if(+$('time').value>=54){stop();return;}$('time').value=+$('time').value+1;render();},250);});document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});render();})();
